package obsgen

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/VMAFx/vmafx/pkg/observability/metricdef"
)

// metricsReference renders the metric reference page from metricdef.
func metricsReference() []byte {
	var b strings.Builder
	b.WriteString(`<!-- markdownlint-disable MD013 -->
<!-- GENERATED by tools/obsgen from pkg/observability/metricdef; do not edit. Regenerate: go run ./tools/obsgen -write -->
# Metric reference

Every metric family the VMAFx services serve on their Prometheus ` + "`/metrics`" + ` page,
generated from the one definition the services build their collectors from
(` + "`pkg/observability/metricdef`" + `). Where each component serves the page and how to
scrape it is in the [observability guide](../development/observability.md).

Each component also serves the Go runtime and process collectors of the
Prometheus client library (` + "`go_*`" + `, ` + "`process_*`" + `).

## Families

| Family | Type | Unit | Labels | Served by | Max series | Description |
| --- | --- | --- | --- | --- | --- | --- |
`)
	for _, f := range metricdef.All() {
		fmt.Fprintf(&b, "| `%s` | %s | %s | %s | %s | %d | %s |\n",
			f.Name, f.Kind, f.Unit, labelList(f), emitterList(f), f.MaxSeries(), f.Help)
	}
	b.WriteString(`
Max series is the most series one process can serve for the family: the
product of its label bounds, times the bucket series plus ` + "`_sum`" + ` and ` + "`_count`" + ` for a
histogram. Read at scrape time: ` + scrapedList() + `.

## Labels

A label with a closed value set takes one of its values or ` + "`" + metricdef.Overflow + "`" + `. An open label
reports at most its limit of distinct values per process; every later value is
merged under ` + "`" + metricdef.Overflow + "`" + ` (counts add up, ages take the oldest), so a series is
never dropped. An empty value is reported as ` + "`" + metricdef.None + "`" + `.

| Label | Values | Source |
| --- | --- | --- |
`)
	for _, l := range uniqueLabels() {
		fmt.Fprintf(&b, "| `%s` | %s | %s |\n", l.Name, labelValues(l), l.Doc)
	}
	return []byte(b.String())
}

func labelList(f metricdef.Family) string {
	if len(f.Labels) == 0 {
		return "none"
	}
	names := f.LabelNames()
	for i := range names {
		names[i] = "`" + names[i] + "`"
	}
	return strings.Join(names, ", ")
}

func emitterList(f metricdef.Family) string {
	names := make([]string, len(f.Emitters))
	for i, c := range f.Emitters {
		names[i] = string(c)
	}
	return strings.Join(names, ", ")
}

func labelValues(l metricdef.Label) string {
	if len(l.Values) == 0 {
		return "open, at most " + strconv.Itoa(l.Limit)
	}
	quoted := make([]string, len(l.Values))
	for i, v := range l.Values {
		quoted[i] = "`" + v + "`"
	}
	return strings.Join(quoted, ", ")
}

// scrapedList names the families read at scrape time.
func scrapedList() string {
	var names []string
	for _, f := range metricdef.All() {
		if f.Scraped {
			names = append(names, "`"+f.Name+"`")
		}
	}
	return strings.Join(names, ", ")
}

// uniqueLabels returns each label of the definition once, in order of first
// use.
func uniqueLabels() []metricdef.Label {
	var out []metricdef.Label
	seen := map[string]bool{}
	for _, f := range metricdef.All() {
		for _, l := range f.Labels {
			if !seen[l.Name] {
				seen[l.Name] = true
				out = append(out, l)
			}
		}
	}
	return out
}
